//! Replay of two real CN28 captures through the decoder (evc04#159).
//!
//! Verbatim probe windows recorded off the box on 2026-08-16 with a `raw-debug`
//! image — the first at the original fixed 2 s auto-poll, the second at a jittered
//! interval (which made no difference, see the issue). In both, the box's splice
//! destroys the `P1:` label on the head of every burst while `P2:`/`P3:` arrive
//! clean, so a decoder anchoring at the start of the line loses phase 1 entirely.
//! These pin that all three phases come back.

use evc04_cn28_core::probe::cn28::{Cn28Snapshot, LineReassembler};

const CAPTURE_FIXED: &[&str] = &["","4d50206c622063757272656e743a20360a65764d50206c622063757272656e743a20365f6f666665","724d50206c622063757272656e743a20366220313a09563a2032333936373509413a20343009573a20330957683a203135303139300a50323a09563a2032333434353709413a20313809573a20300957683a203134373936350a50333a09563a2032333639313109413a20313809573a20300957683a203134393430300a0a4d50204d50206c622063757272656e743a2036206375","2063757272656e743a20300a0a6d61785f6f6666657265645f63757272656e743a2031360a6c622063757272656e743a330a0a54454d50206c622063757272656e743a20366375724d50206c622063757272656e743a2036637572","","4d50206c622063757272656e743a20362032334d50206c622063757272656e743a203657683a",""];
const CAPTURE_JITTERED: &[&str] = &["656d703a2033312043200a573a204d50206c622063757272656e743a203609563a","","664d50206c622063757272656e743a2036360a6c4d50206c622063757272656e743a203650206c","","4d50206c622063757272656e743a20364d50204d50206c622063757272656e743a20362063","754d50206c622063757272656e743a20366665723a09563a2032333532373009413a20343509573a20330957683a203135303139300a50323a09563a2032333336343409413a20313809573a20300957683a203134373936350a50333a09563a2032333735373609413a20313809573a20300957683a203134393430300a0a4d50204d50206c622063757272656e743a20366d703a","372063757272656e743a20300a0a6d61785f6f6666657265645f63757272656e743a2031360a6c622063757272656e743a330a0a54454d50206c622063757272656e743a20366375656d703a2033312043200a4d50204d50206c622063757272656e743a20364d50","203a09563a2032333630323409413a20343009573a20330957683a203135303139300a50323a09563a2032333234393109413a20313809573a20300957683a203134373936350a50333a09563a2032333737363809413a20313809573a20300957683a203134393430300a0a4d50204d50206c622063757272656e743a20364d5020","4d50206c622063757272656e743a20366220634d50206c622063757272656e743a2036622063","","4d50206c622063757272656e743a20360a54454d50206c622063757272656e743a20360a65764d50206c622063757272656e743a20365f6f66","3a09563a2032333632303109413a20343509573a20330957683a203135303139300a50323a09563a2032333239363409413a20313809573a20300957683a203134373936350a50333a09563a2032333734373209413a20313809573a20300957683a203134393430300a0a0a54454d50206c622063757272656e743a20360a54454d50206c622063757272656e743a20360a6576","4d50206c622063757272656e743a2036683a202063757272656e743a20300a0a6d61785f6f6666657265645f63757272656e743a2031360a6c622063757272656e743a330a0a54454d50206c622063757272656e743a20366c62204d50206c622063757272656e743a20366c62","203a09563a2032333532393909413a20343009573a20330957683a203135303139300a50323a09563a2032333436303509413a20313809573a20300957683a203134373936350a50333a09563a2032333730343409413a20313809573a20300957683a203134393430300a0a6c62204d50206c622063757272656e743a20360a54656d703a2033312043200a0a5445","4d50206c622063757272656e743a20365f6f664d50206c622063757272656e743a2036360a6c","","682063757272656e743a20300a0a6d61785f6f6666657265645f63757272656e743a2031360a6c622063757272656e743a330a0a54454d50206c622063757272656e743a20360a54656d703a2033312043200a0a54454d50",""];

fn replay(windows: &[&str]) -> Cn28Snapshot {
    let mut snap = Cn28Snapshot::new();
    let mut asm = LineReassembler::new();
    for w in windows {
        let bytes: Vec<u8> = (0..w.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&w[i..i + 2], 16).unwrap())
            .collect();
        for line in asm.push(&bytes) {
            snap.apply_line(&String::from_utf8_lossy(&line), 0);
        }
    }
    snap
}

#[test]
fn the_fixed_cadence_capture_yields_all_three_phases() {
    let snap = replay(CAPTURE_FIXED);
    assert!(snap.phases[0].is_some(), "phase 1 lost: {snap:?}");
    assert!(snap.phases[1].is_some(), "phase 2 lost");
    assert!(snap.phases[2].is_some(), "phase 3 lost");
}

#[test]
fn the_jittered_capture_yields_all_three_phases() {
    let snap = replay(CAPTURE_JITTERED);
    assert!(snap.phases[0].is_some(), "phase 1 lost: {snap:?}");
    assert!(snap.phases[1].is_some(), "phase 2 lost");
    assert!(snap.phases[2].is_some(), "phase 3 lost");
}

#[test]
fn the_recovered_phase_1_carries_the_boxs_own_counter() {
    // P1's energy counter read 150190 Wh throughout both captures; phases 2 and 3
    // sat ~2 kWh below it, so a mislabelled phase would be obvious here.
    let snap = replay(CAPTURE_JITTERED);
    assert_eq!(snap.phases[0].unwrap().wh, 150190);
    assert_eq!(snap.phases[1].unwrap().wh, 147965);
    assert_eq!(snap.phases[2].unwrap().wh, 149400);
}
